+/* Add a fixed sequence of BQR report fields, stopping at the first field that
+ * is not fully present so truncated reports cannot read past the end. */
+static unsigned
+android_bqr_add_fields(proto_tree *tree, tvbuff_t *tvb, unsigned offset,
+                       const int *const *fields, const uint8_t *sizes, size_t count)
+{
+    size_t i;
+
+    for (i = 0; i < count && tvb_captured_length_remaining(tvb, offset) >= sizes[i]; i++) {
+        proto_tree_add_item(tree, *fields[i], tvb, offset, sizes[i],
+                            sizes[i] == 1 ? ENC_NA : ENC_LITTLE_ENDIAN);
+        offset += sizes[i];
+    }
+    return offset;
+}
